        rule: '- Sened-i İttifak (1808): Padişahın yetkileri ilk kez sınırlandırıldı (Ayanlar ile II. Mahmut).\n- Tanzimat Fermanı (1839): Hukukun üstünlüğü ilkesi kabul edildi, herkes kanun önünde eşit sayıldı.\n- Islahat Fermanı (1856): Gayrimüslimlere ekstra haklar verildi.\n- I. Meşrutiyet (1876): Kanun-i Esasi ilan edildi, ilk kez halk yönetime katıldı (Mebusan ve Ayan Meclisi).\n- Fikir Akımları: Osmanlıcılık (Ziya Paşa, Namık Kemal), İslamcılık (II. Abdülhamit), Türkçülük (Ziya Gökalp, Yusuf Akçura), Batıcılık (Tevfik Fikret).',
        examTip: 'Tanzimat ve Islahat fermanlarında HALK HAREKETİ YOKTUR; devlet adamlarının fermanıyla tepeden inme ilan edilmiştir!',
        iconEmoji: '⚖️',
      ),
