        conceptTitle: 'Doğu ve Güney Cepheleri - Temel Kavramlar',
        rule: '- Doğu Cephesi: Kazım Karabekir, Gümrü Antlaşması (Ermeniler ile, TBMM\'yi tanıyan ilk devlet).\n- Güney Cephesi: Kuvayımilliye, Maraş (Kahraman), Antep (Gazi), Urfa (Şanlı). 1921 Ankara Antlaşması ile kapandı.\n- Batı Cephesi:\n  1. I. İnönü Zaferi (M-İ-L-A-T: Moskova Ant., İstiklal Marşı, Londra Konf., Afganistan Dostluk, Teşkilat-ı Esasiye).\n  2. II. İnönü Zaferi (\'Siz orada sadece düşmanı değil, milletin makus talihini de yendiniz\').\n  3. Kütahya-Eskişehir: Tek yenilgi. Maarif Kongresi toplandı. Tekalif-i Milliye Emirleri yayımlandı.\n  4. Sakarya Meydan Muharebesi: 22 gün 22 gece. \'Hattı müdafaa yoktur, sathı müdafaa vardır.\' Mustafa Kemal\'e Mareşallik ve Gazilik unvanı verildi. Kars Antlaşması ile Doğu sınırı kesinleşti.\n  5. Büyük Taarruz (Başkomutanlık): \'Ordular ilk hedefiniz Akdeniz\'dir, ileri!\' Mudanya Ateşkesi imzalandı.\n- Lozan Barış Antlaşması (24 Temmuz 1923): Türkiye\'nin tapu senedi.',
        examTip: 'Doğu sınırını çizen antlaşmalar şifresi: G-A-K (Gümrü -> Moskova -> Kars). Kars Antlaşması ile Doğu sınırı KESİN çizilmiştir!',
